import pandas as pd, numpy as np

res = pd.read_csv('data/pass_residual_traces.tsv', sep='\t')
models = ['residual_model_A_mm_s', 'residual_model_B_mm_s', 'residual_model_C_mm_s']

# Detailed cross-model correlations per pass
print('Cross-model Pearson correlations per pass:')
for pid in sorted(res['pass_id'].unique()):
    sub = res[res['pass_id'] == pid]
    for i, m1 in enumerate(models):
        for m2 in models[i+1:]:
            r = sub[m1].corr(sub[m2])
            if not np.isnan(r):
                print(f'  {pid}: {m1.replace(\"residual_model_\",\"M\").replace(\"_mm_s\",\"\")} vs {m2.replace(\"residual_model_\",\"M\").replace(\"_mm_s\",\"\")}: r={r:.4f}')

# Check if residuals are similar across models within a pass
print('\nModel similarity (mean absolute difference between models):')
for pid in sorted(res['pass_id'].unique())[:5]:
    sub = res[res['pass_id'] == pid]
    for mc in models:
        sub[mc + '_pivot'] = sub[mc]
    pivot = sub.pivot_table(index='relative_time_min', columns='pass_id', values=models)
    # Actually need to compare model-to-model
    diffs = []
    for i, m1 in enumerate(models):
        for m2 in models[i+1:]:
            d = np.abs(sub[m1] - sub[m2]).mean()
            diffs.append((m1, m2, d))
    for m1, m2, d in diffs:
        print(f'  {pid}: |{m1.replace(\"residual_model_\",\"M\").replace(\"_mm_s\",\"\")} - {m2.replace(\"residual_model_\",\"M\").replace(\"_mm_s\",\"\")}| mean_diff={d:.6f}')
